从python更改


```python
import os
import yaml
import time
import requests

CONFIG = {
    'name': 'Xch13',
    'model': {
        'url': 'https://xxx/v1/chat/completions',
        'name': 'xxx',
        'api_key': 'Bearer xxx'
    },
    'retry': {
        'attempts': 3,
        'delay': 20
    },
    'output': {
        'descriptions_yaml': 'folders_description.yaml'
    },
    'prompt': '''# 角色：  Windows系统专家

# 背景信息：  在Windows操作系统中，AppData文件夹通常包含应用程序数据，这些数据可能是设置、配置文件、缓存文件等。

# 工作流程/工作任务：  
- 识别并分析AppData下的[xxx]文件夹中的[xxx]子文件夹。
- 研究该子文件夹的具体用途。
- 提供简洁准确的描述。

# 输入提示：  请简述Windows系统中AppData下的[{}]文件夹中的[{}]子文件夹的用途。

# 输出示例：  
- 软件：Chrome\n作用：存储Chrome浏览器的用户数据，如历史记录、书签、密码等。\n功能：用户数据管理\n

- 软件：Dropbox\n作用：存储Dropbox同步的文件和文件夹。\n功能：文件同步与存储\n

- 软件：Microsoft Office\n作用：存储Office应用程序的设置和个性化选项。\n功能：应用程序配置和个性化设置\n

# 注意事项：  
- 描述应简洁明了，不超过50字。
- 确保描述的准确性，避免误导用户。'''
}


class YamlManager:
    def __init__(self, filename, name):
        self.filename = filename
        self.required_data = {
            'name': name,
            'Local': {},
            'LocalLow': {},
            'Roaming': {}
        }
        self.data = self.read()
        self.ensure_required_data()

    def add_data(self, section, foldername, description):
        """添加数据到YAML文件，确保没有空值"""
        if not section or not foldername or not description:
            print(f"跳过空值数据：section={section}, folder={foldername}")
            return

        if section not in ['Local', 'LocalLow', 'Roaming']:
            print(f"无效的section: {section}")
            return

        if description is None or str(description).strip() == '':
            description = "未知用途的文件夹"

        if section not in self.data:
            self.data[section] = {}

        self.data[section][foldername] = description
        self.save()

    def save(self):
        """保存YAML文件，确保保持结构"""
        base_structure = {
            'name': self.data.get('name', self.required_data['name']),
            'Local': self.data.get('Local', {}),
            'LocalLow': self.data.get('LocalLow', {}),
            'Roaming': self.data.get('Roaming', {})
        }

        self.data.update(base_structure)

        with open(self.filename, 'w', encoding='utf-8') as file:
            yaml.dump(self.data, file, allow_unicode=True, indent=4, sort_keys=False)

    def read(self):
        """读取YAML文件，确保基础结构"""
        if os.path.exists(self.filename):
            with open(self.filename, 'r', encoding='utf-8') as file:
                data = yaml.safe_load(file) or {}
        else:
            data = {}

        base_structure = {
            'name': self.required_data['name'],
            'Local': {},
            'LocalLow': {},
            'Roaming': {}
        }

        for key, value in base_structure.items():
            if key not in data:
                data[key] = value

        return data

    def ensure_required_data(self):
        """确保必要数据存在"""
        for key, value in self.required_data.items():
            if key not in self.data:
                self.data[key] = value
            elif isinstance(value, dict) and isinstance(self.data[key], dict):
                self.data[key] = {**value, **self.data[key]}
        self.save()


class AppDataAnalyzer:
    def __init__(self):
        self.config = CONFIG
        self.yaml_manager = YamlManager(
            self.config['output']['descriptions_yaml'],
            self.config['name']
        )

    def analyze_appdata_folder(self, dir_1, dir_2):
        """分析AppData文件夹，使用循环实现重试"""
        data = {
            "messages": [
                {
                    "role": "system",
                    "content": self.config['prompt']
                },
                {
                    "role": "user",
                    "content": f"请简述Windows系统中AppData下的[{dir_1}]文件夹中的[{dir_2}]子文件夹的用途。"
                }
            ],
            "model": self.config['model']['name']
        }

        attempts = self.config['retry']['attempts']
        delay = self.config['retry']['delay']

        while attempts > 0:
            try:
                response = requests.post(
                    url=self.config['model']['url'],
                    headers={
                        "Authorization": self.config['model']['api_key'],
                        "Content-Type": "application/json"
                    },
                    json=data
                )
                content = response.json()['choices'][0]['message']['content']
                return content if content else "未知用途的文件夹"
            except Exception as e:
                attempts -= 1
                if attempts > 0:
                    print(f"分析出错，剩余尝试次数：{attempts}，错误：{str(e)}")
                    time.sleep(delay)
                else:
                    print(f"分析最终失败：{str(e)}")
                    return "分析过程中出现错误"

    def get_appdata_paths(self):
        """获取AppData路径"""
        appdatapath = os.getenv('APPDATA')
        if not appdatapath:
            raise EnvironmentError("无法找到AppData路径。")

        basepath = os.path.dirname(appdatapath)
        return {
            "Local": os.path.join(basepath, 'Local'),
            "LocalLow": os.path.join(basepath, 'LocalLow'),
            "Roaming": appdatapath
        }

    def listdirectories(self, basepath):
        """列出目录，处理错误情况"""
        directories = []
        try:
            for item in os.listdir(basepath):
                itempath = os.path.join(basepath, item)
                if os.path.isdir(itempath):
                    directories.append(item)
        except PermissionError:
            print(f"没有权限访问: {basepath}")
        except FileNotFoundError:
            print(f"找不到路径: {basepath}")

        return directories or ["无法访问或空目录"]

    def process_directories(self):
        """处理目录信息，直接写入YAML"""
        appdata_paths = self.get_appdata_paths()

        for section, path in appdata_paths.items():
            folders = self.listdirectories(path)
            for folder in folders:
                if folder == "无法访问或空目录":
                    continue

                if folder in self.yaml_manager.data.get(section, {}):
                    print(f"已保存 {section} {folder}\n",
                          self.yaml_manager.data[section].get(folder))
                else:
                    res = self.analyze_appdata_folder(section, folder)
                    self.yaml_manager.add_data(section, folder, res)
                    print(f"新保存 {section} {folder}\n", res)
                    time.sleep(1)


def main():
    analyzer = AppDataAnalyzer()
    analyzer.process_directories()


if __name__ == "__main__":
    main()
```
